{
  "headline": "FDA's records trace our supply to plants with OAI classifications and a Warning Letter within 8 days of the shortage posting",
  "headline_cites": ["D6", "D8", "D12"],
  "sentences": [
    {
      "text": "FDA first posted the midazolam hydrochloride shortage on 2020-04-02 and it remains current as of 2026-10-21.",
      "cites": ["E59", "D20"]
    },
    {
      "text": "The shortage posting lists Hospira, Inc. and Hikma Pharmaceuticals USA, Inc. among the affected manufacturers.",
      "cites": ["E56", "E57"]
    },
    {
      "text": "Hospira's plant (FEI 1925262) received an OAI classification after an inspection ending 2018-08-15, 596 days before the shortage posting.",
      "cites": ["D6", "E30"]
    },
    {
      "text": "Pfizer Healthcare India Private Limited (FEI 3008316085) received an OAI classification after an inspection ending 2019-09-06, 209 days before the shortage posting.",
      "cites": ["D8", "E40"]
    },
    {
      "text": "A Warning Letter was issued to Pfizer Healthcare India Private Limited on 2020-03-25, 8 days before the shortage posting.",
      "cites": ["D12", "E42"]
    },
    {
      "text": "Hospira's plant (FEI 1925262) received another OAI classification letter dated 2020-04-22, 20 days after the shortage posting.",
      "cites": ["D13", "E30"]
    },
    {
      "text": "The rule-based best option is to buy from A-S Medication Solutions, which is not on FDA's shortage list today.",
      "cites": ["D17"]
    }
  ]
}
